action.code:
std::vector<Node> nodes;
nodes.reserve(rt.number_of_vertices());

// Iterate through all finite vertices
for (RT::Finite_vertices_iterator vit = rt.finite_vertices_begin(); 
     vit != rt.finite_vertices_end(); ++vit) {

    RT::Vertex_handle vh = vit;
    const Weighted_point& wp = vh->point();
    const Point& bare_point = rt.bare_point(vh);

    // Create node structure
    Node node;

    // Extract position
    node.position[0] = bare_point.x();
    node.position[1] = bare_point.y();
    node.position[2] = bare_point.z();

    // Extract mass (weight component)
    node.mass = wp.weight();

    // Calculate velocity - using similar pattern to Adhesion::velocity
    // Find a cell containing this vertex
    RT::Cell_handle cell;
    bool found = false;
    for (RT::Cell_iterator cit = rt.finite_cells_begin(); 
         cit != rt.finite_cells_end(); ++cit) {
        for (int i = 0; i < 4; ++i) {
            if (cit->vertex(i) == vh) {
                cell = cit;
                found = true;
                break;
            }
        }
        if (found) break;
    }

    if (found) {
        // Calculate velocity based on cell neighbors
        Vector vel(0, 0, 0);
        int count = 0;

        // Simple velocity calculation - average of neighbor velocities
        for (int i = 0; i < 4; ++i) {
            RT::Vertex_handle neighbor = cell->vertex(i);
            if (neighbor != vh && neighbor != RT::Vertex_handle()) {
                const Point& neighbor_point = rt.bare_point(neighbor);
                Vector diff = neighbor_point - bare_point;
                vel = vel + diff;
                count++;
            }
        }

        if (count > 0) {
            vel = vel / count;
        }

        node.velocity[0] = vel.x();
        node.velocity[1] = vel.y();
        node.velocity[2] = vel.z();
    } else {
        // Fallback velocity
        node.velocity[0] = 0.0;
        node.velocity[1] = 0.0;
        node.velocity[2] = 0.0;
    }

    // Determine node type based on edge count
    int edge_count = 0;

    // Count edges connected to this vertex
    std::set<RT::Vertex_handle> neighbors;
    RT::Cell_circulator circ = rt.incident_cells(vh);
    RT::Cell_circulator done = circ;

    if (circ != 0) {
        do {
            for (int i = 0; i < 4; ++i) {
                RT::Vertex_handle neighbor = circ->vertex(i);
                if (neighbor != vh && neighbor != RT::Vertex_handle()) {
                    neighbors.insert(neighbor);
                }
            }
            ++circ;
        } while (circ != done);
    }

    edge_count = neighbors.size();

    // Classify node type
    switch (edge_count) {
        case 0:
            node.node_type = Node::VOID;
            break;
        case 1:
        case 2:
            node.node_type = Node::KURTOPARABOLIC;
            break;
        case 3:
        case 4:
            node.node_type = Node::WALL;
            break;
        case 5:
            node.node_type = Node::FILAMENT;
            break;
        case 6:
            node.node_type = Node::CLUSTER;
            break;
        default:
            node.node_type = Node::UNDEFINED_NODE_TYPE;
            break;
    }

    nodes.push_back(std::move(node));
}

return nodes;

